import{_ as e,o as s,c as t,a0 as n}from"./chunks/framework.bcCluOOn.js";const h=JSON.parse('{"title":"Database Entities","description":"","frontmatter":{},"headers":[],"relativePath":"web/database.md","filePath":"web/database.md"}'),i={name:"web/database.md"};function o(d,a,c,r,p,l){return s(),t("div",null,[...a[0]||(a[0]=[n(`<h1 id="database-entities" tabindex="-1">Database Entities <a class="header-anchor" href="#database-entities" aria-label="Permalink to &quot;Database Entities&quot;">​</a></h1><p>AAYU comes with native, thread-safe SQLite integration baked directly into the language. You do not need Prisma, TypeORM, or raw SQL queries to persist data.</p><h2 id="declaring-entities" tabindex="-1">Declaring Entities <a class="header-anchor" href="#declaring-entities" aria-label="Permalink to &quot;Declaring Entities&quot;">​</a></h2><p>An <code>entity</code> in AAYU maps directly to a relational database table.</p><div class="language-aayu vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">aayu</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>use db.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>entity Product.</span></span>
<span class="line"><span>    text name.</span></span>
<span class="line"><span>    number price.</span></span>
<span class="line"><span>    boolean in_stock.</span></span>
<span class="line"><span>end.</span></span></code></pre></div><p>When AAYU compiles this code, it automatically generates a SQLite database, handles the migrations, and ensures the table <code>Product</code> exists with the correct column types (<code>TEXT</code>, <code>REAL</code>, <code>INTEGER</code>).</p><h2 id="database-operations" tabindex="-1">Database Operations <a class="header-anchor" href="#database-operations" aria-label="Permalink to &quot;Database Operations&quot;">​</a></h2><p>AAYU provides built-in database keywords to interact with your entities seamlessly:</p><h3 id="creating-records" tabindex="-1">Creating Records <a class="header-anchor" href="#creating-records" aria-label="Permalink to &quot;Creating Records&quot;">​</a></h3><div class="language-aayu vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">aayu</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>create Product &quot;name&quot; &quot;Laptop&quot; &quot;price&quot; 1200 &quot;in_stock&quot; true.</span></span></code></pre></div><h3 id="finding-records" tabindex="-1">Finding Records <a class="header-anchor" href="#finding-records" aria-label="Permalink to &quot;Finding Records&quot;">​</a></h3><div class="language-aayu vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">aayu</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>map product_data.</span></span>
<span class="line"><span>find Product 1 into product_data.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>print product_data[&quot;name&quot;].</span></span></code></pre></div><h3 id="fetching-all-records" tabindex="-1">Fetching All Records <a class="header-anchor" href="#fetching-all-records" aria-label="Permalink to &quot;Fetching All Records&quot;">​</a></h3><div class="language-aayu vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">aayu</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>map all_products.</span></span>
<span class="line"><span>find_all Product into all_products.</span></span></code></pre></div><h3 id="updating-records" tabindex="-1">Updating Records <a class="header-anchor" href="#updating-records" aria-label="Permalink to &quot;Updating Records&quot;">​</a></h3><div class="language-aayu vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">aayu</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>update Product 1 &quot;price&quot; 999.</span></span></code></pre></div><h3 id="deleting-records" tabindex="-1">Deleting Records <a class="header-anchor" href="#deleting-records" aria-label="Permalink to &quot;Deleting Records&quot;">​</a></h3><div class="language-aayu vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">aayu</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>delete Product 1.</span></span></code></pre></div><p>All interactions use an underlying Write-Ahead Log (WAL) architecture to ensure maximum concurrency when accessed from the web server.</p>`,19)])])}const b=e(i,[["render",o]]);export{h as __pageData,b as default};
